css:
/*
 * 手机端适配。不改 PiWeb，只在经代理的远程页面上生效
 * （本机直连 127.0.0.1:30141 的桌面页面完全不加载它）。
 *
 * 取值参照 dsh-remote 为 DSH 定的那套移动适配（同作者），并针对 PiWeb 的实测问题：
 * 390px 下输入框 304px、markdown 表格 442px 超出视口、底部统计行被截断。
 */
@media (max-width: 840px) {
	/* 1) 输入框自适应高度失控。
	   实测：视口 390 → 304px，500 → 43px，700+ → 22px；而自然内容高始终 22px。
	   原因在 ChatInput 的 autoSize()：它把"被 flex 拉伸后"的 scrollHeight 写进了
	   inline height，写回后又把自己撑住，形成自锁。inline 样式不是 important，
	   所以这里用 max-height !important 把它夹住。 */
	textarea {
		max-height: 132px !important;
		overflow-y: auto !important;
	}

	/* 2) Markdown 宽表格超出视口被裁掉（实测 442 > 390，body 又是 overflow-x:hidden，
	   等于右侧内容既看不到也滑不到）。让表格自己横向滚动。 */
	.md table {
		display: block !important;
		max-width: 100% !important;
		overflow-x: auto !important;
		-webkit-overflow-scrolling: touch;
	}

	/* 3) 全局溢出护栏（dsh-remote 同款）：任何一块都不许把文档撑宽 */
	html,
	body {
		max-width: 100vw !important;
		overflow-x: hidden !important;
	}
	pre {
		max-width: 100% !important;
		overflow-x: auto !important;
		-webkit-overflow-scrolling: touch;
	}
	img,
	svg,
	video,
	canvas {
		max-width: 100% !important;
	}

	/* 4) 底部统计行原本 nowrap + ellipsis，手机上「| 输入 2…」之后永远看不到。
	   改成可横向滑动，滚动条隐藏，信息不再丢。 */
	div.text-center > div.overflow-hidden.text-ellipsis.whitespace-nowrap {
		overflow-x: auto !important;
		overflow-y: hidden !important;
		text-overflow: clip !important;
		-webkit-overflow-scrolling: touch;
		scrollbar-width: none;
	}
	div.text-center > div.overflow-hidden.text-ellipsis.whitespace-nowrap::-webkit-scrollbar {
		display: none;
	}

	/* 5) 给手机的手势条留位置（没有 insets 的设备 env() 为 0，等于没写） */
	.pi-main {
		padding-bottom: env(safe-area-inset-bottom) !important;
	}

	/* 6) 左上角的抽屉按钮。原来是个悬浮的圆角方块（12px/12px、34px），盖在内容上、
	   和右边那排图标也不在一条水平线上。按 dsh-remote 对 DSH 左侧的做法收成贴角圆形，
	   尺寸和位置改成与右侧图标完全一致（实测右侧图标是 top 12 / 30×30，中心 y=27），
	   这样整行对齐，按钮底边 42 也在头部分隔线（y=43）之上，不会压住那条线。 */
	.pi-mobile-menu {
		width: 30px !important;
		height: 30px !important;
		border-radius: 999px !important;
		left: calc(env(safe-area-inset-left) + 12px) !important;
		top: calc(env(safe-area-inset-top) + 12px) !important;
	}
	.pi-main > .hairline-b {
		padding-left: 52px !important;
	}

	/* 7) 右侧大纲导轨是绝对定位的（right-2 + 约 34px 宽的竖条），正文和用户气泡
	   会从它下面穿过去。不动条宽——那是层级信息——而是把导轨贴边收窄，
	   再给滚动区留出它实际占的宽度。 */
	.outline-rail {
		right: 2px !important;
	}
	.outline-rail > div {
		padding-left: 6px !important;
		padding-right: 2px !important;
	}
	.pi-main div.min-h-0.flex-1.overflow-y-auto {
		padding-right: 30px !important;
	}

	/* 8) 设置弹窗：高度用 100vh（移动端的大视口），内容列又没有 min-height:0
	   也没有 overflow-y，于是 1986px 的内容被 overflow:hidden 裁在 828px 里，
	   手机上完全滑不动。实测 client=828 / scroll=1986。 */
	.settings-dialog {
		height: calc(100vh - 16px) !important;
	}
	.settings-dialog > div:not(.settings-nav) {
		min-height: 0 !important;
		overflow-y: auto !important;
		-webkit-overflow-scrolling: touch;
	}

	/* 9) 模型 / 思考等级浮层锚在胶囊自己的 relative 容器上，right-0 是**胶囊**右缘，
	   312px 往左展开就顶出屏幕左边（实测 left 为负）。把胶囊容器解除定位，
	   浮层改用整张输入卡（上一层 relative）做定位父级，right-0 落在卡片右缘就装得下。
	   :has() 在移动端 Safari 15.4+ / Chrome 105+ 都可用。 */
	div.relative:has(> button.chip[aria-haspopup="menu"]) {
		position: static !important;
	}

	/* 10) 设置→模型 的提供方卡片：那一行是 nowrap，中间的名字列被右侧一串按钮挤成
	   0 宽（实测 w=0），于是「凭据: auth.json」竖着拆行、「编辑」拆成「编/辑」、
	   右侧的按钮还被裁掉。手机上让这行能换行，并给名字列一个真实的最小宽度。 */
	.settings-dialog div.flex.items-center.gap-3:has(> div.min-w-0.flex-1) {
		flex-wrap: wrap !important;
		row-gap: 8px !important;
	}
	.settings-dialog div.flex.items-center.gap-3:has(> div.min-w-0.flex-1) > div.min-w-0.flex-1 {
		flex: 1 1 140px !important;
		min-width: 140px !important;
	}

	/* 11) 设置里 Row 那一套（[文字列][控件列] 两栏）。控件列是 flex-none，
	   有的行右侧很宽（「开关 + 两个数字输入框」≈272px、「繁忙时 Enter」的下拉≈233px），
	   于是 390px 下文字列只剩 70px 左右，中文按每行一两字竖排，行高被撑到
	   122px / 218px（实测 70×122、69×218）。
	   试过的几种写法与实测结论：
	     - 只给文字列 flex 增长权重：完全没用（那行没有空闲空间）
	     - 只缩小 gap：只能缓解（70×122 → 86×98）
	     - 让所有 Row 都上下排（flex:1 1 100%）：能修好，但把本来正常的行也撑高
	       （界面语言 53→85、字体步进 95→105），是密度回退
	     - 正解：文字列 flex-basis 设 0、只留 min-width 当"不许被压到多窄"的下限。
	       换行判断用的是 flex-basis（max-content 会很大，所以上一版全换行了），
	       设成 0 之后判断就只看 min-width：
	         控件窄的行（界面语言 77px、字体步进 116px）→ 仍并排，保持紧凑
	         控件宽的行（272px / 233px）→ 控件换到下一行，文字拿满 326px
	   实测：界面语言 53 不变、界面字体 95→71、繁忙时Enter 239→135、
	         自动压缩 143→111、自动重试 119→111，全部不再竖排。 */
	.settings-dialog div.hairline-b.gap-6 {
		flex-wrap: wrap !important;
		gap: 8px !important;
	}
	.settings-dialog div.hairline-b.gap-6 > div.min-w-0 {
		flex: 1 1 0 !important;
		min-width: 45% !important;
	}
	.settings-dialog div.hairline-b.gap-6 > div.flex-none > div.flex.items-center {
		flex-wrap: wrap !important;
		justify-content: flex-end !important;
		row-gap: 6px !important;
	}

	/* 12) 外观主题卡片。卡片是 flex: 1 1 150px 的两列网格，但左右各留 32px 内边距，
	   159px 的卡片只剩 95px 给标题，于是「石灰与煤炭」「亚麻与苔绿」掉到第二行，
	   卡片高度变成 110px 而其余是 88px，网格参差（实测 6 张卡：4 张 88 / 2 张 110）。
	   把左右内边距收到 10px，6 张卡全部回到 88px，标题一行放得下。 */
	.settings-dialog button[aria-pressed] {
		padding-left: 10px !important;
		padding-right: 10px !important;
	}

	/* 13) 可点目标偏小（实测：字体步进器 26×26、reset 48×24、开关 36×20）。
	   只扩**热区**，绝不改可见尺寸：开关的滑块位置在 PiWeb 里是写死的
	   （left: 18px / 2px），把开关拉宽会让滑块错位、变成被拉长的怪药丸
	   —— 我第一版写的 min-width:44px 就是这个后果，用户报了"启动按钮好丑"。
	   另外这里只做**纵向**扩张（左右不扩）：字体步进器 −/+/ 之间只有 8px，
	   横向扩到 44px 会让两个按钮的热区重叠约 10px，点 − 反而命中 +。 */
	.settings-dialog .icon-btn,
	.settings-dialog button.h-6,
	.settings-dialog button.h-5,
	.settings-dialog [role="switch"] {
		position: relative !important;
	}
	.settings-dialog .icon-btn::after,
	.settings-dialog button.h-6::after,
	.settings-dialog button.h-5::after,
	.settings-dialog [role="switch"]::after {
		content: "" !important;
		position: absolute !important;
		left: 0 !important;
		right: 0 !important;
		top: 50% !important;
		height: max(100%, 44px) !important;
		transform: translateY(-50%) !important;
		border-radius: 999px !important;
	}
}

/* 手机上的浮层统一兜底：不许比屏幕宽，不许比屏幕高，超出就自己滚。 */
@media (max-width: 840px) {
	.popover {
		max-width: calc(100vw - 16px) !important;
		max-height: 420px !important;
		overflow-y: auto !important;
		-webkit-overflow-scrolling: touch;
	}
}

/* 上下文弹窗（圆环）额外收紧：它右对齐在圆环上，而圆环离屏幕右缘还有 60-70px
   （主输入框 ~71px、旁聊面板 ~63px）。上面「统一兜底」的 100vw-16px 在 360px 以下
   的机型仍会把左边顶出屏幕（实测 344px → left −15px、320px → left −39px）。
   这里按视口留出 96px：主输入框与旁聊面板实测 left ≥ 25px，且不越出旁聊面板左缘。 */
@media (max-width: 840px) {
	.popover.pw-context-popover {
		max-width: calc(100vw - 96px) !important;
	}
}

/* 11) 模型名太长时跑马灯。取值与做法照搬 dsh-remote 对 DSH 的：
	   名字窗口固定 28vw 并允许被压缩，装得下就完全不动；装不下时由注入的
	   mobile-fit.js 打上 data-piweb-marquee，再由这里的两份伪元素首尾相接匀速左移。
	   一份走完另一份正好接上（travel 已含间隔），所以循环处看不出接缝。 */
@media (max-width: 840px) {
	button.chip[aria-haspopup="menu"] > span.truncate {
		min-width: 0 !important;
		max-width: 28vw !important;
	}
	[data-piweb-marquee] {
		position: relative !important;
		display: block !important;
		width: 28vw !important;
		flex: none !important;
		text-overflow: clip !important;
		white-space: nowrap !important;
		overflow: hidden !important;
		text-indent: 0 !important;
		contain: layout paint !important;
		color: transparent !important;
		line-height: 20px !important;
	}
	[data-piweb-marquee]::before,
	[data-piweb-marquee]::after {
		content: attr(data-piweb-text);
		position: absolute;
		top: 0;
		left: 0;
		color: var(--piweb-marquee-color, var(--dsw-label-primary));
		font-size: 13px;
		line-height: 20px;
		white-space: nowrap;
		will-change: transform;
		transform: translate3d(0, 0, 0);
		animation: piweb-mfit-marquee var(--piweb-marquee-duration, 8s) linear infinite both;
	}
	[data-piweb-marquee]::after {
		left: var(--piweb-marquee-text, 0px);
	}
	@keyframes piweb-mfit-marquee {
		from { transform: translate3d(0, 0, 0); }
		to { transform: translate3d(calc(-1 * var(--piweb-marquee-text, 0px)), 0, 0); }
	}
}

/* dvh 是"实际可见高度"，比 100vh（移动 Chrome 的大视口）可靠；
   不支持时上面那两条固定值兜底。 */
@supports (height: 100dvh) {
	@media (max-width: 840px) {
		textarea {
			max-height: min(132px, 26dvh) !important;
		}
		.popover {
			max-height: min(60dvh, 420px) !important;
		}
		.settings-dialog {
			height: calc(100dvh - 16px) !important;
		}
	}
}

js:
/*
 * 手机端脚本（配合 mobile-fit.css）。
 *
 * 做两件事：
 * 1) 模型名太长时改成「跑马灯」。做法照搬 dsh-remote 对 DSH 的处理——
 *    名字窗口固定 28vw，装得下就完全不动；装不下时才把两份文本首尾相接匀速左移，
 *    一份走完另一份正好接上，循环没有空档。CSS 负责动画，这里只负责"量"和"打标记"。
 *    为什么必须用 JS 量：纯 CSS 判断不了"是否真的被截断"，只能用省略号一裁了之，
 *    名字的尾巴就永远看不到了。
 * 2) 设置里「文字 + 开关」那种行，手机上点文字也能切开关。
 *    手机断点下这行是上下排（见 mobile-fit.css 第 11 条），文字占满一行、开关缩在下面，
 *    而 PiWeb 只让那个 36×20 的小开关可点 —— 用户点最显眼的标题文字毫无反应，
 *    看起来就是"这个开关坏了"。实测：点文字 0 次请求，点开关才发请求。
 */
(function () {
	"use strict";

	var ATTR = "data-piweb-marquee";
	var TEXT_ATTR = "data-piweb-text";
	var TEXT_VAR = "--piweb-marquee-text";
	var DURATION_VAR = "--piweb-marquee-duration";
	var COLOR_VAR = "--piweb-marquee-color";
	var /** 两份文本之间留的间隔，也是 travel 里多出来的那一段 */
		GAP = 40;
	var /** 每秒移动多少像素，太长就慢一点 */
		SPEED = 22;
	var MIN_CYCLE = 6;
	var ROW_BOUND_ATTR = "data-piweb-row-bound";

	/** 模型胶囊里的名字（ModelSelector 里那个 span.truncate） */
	function label() {
		return document.querySelector('button.chip[aria-haspopup="menu"] > span.truncate');
	}

	function apply() {
		var el = label();
		if (!el) return;
		var text = el.textContent || "";
		if (!text) return;

		// 同一个名字已经标过就别再动它：重设属性会把 CSS 动画从头开始，看起来是"一直重启"
		if (el.hasAttribute(ATTR) && el.getAttribute(TEXT_ATTR) === text) return;

		// 量必须在"静止态"下做：先摘掉标记，否则量到的是被 28vw 框死之后的宽度
		if (el.hasAttribute(ATTR)) el.removeAttribute(ATTR);
		var natural = el.scrollWidth;
		var windowWidth = el.clientWidth;
		if (!windowWidth || natural <= windowWidth + 1) return; // 装得下，什么都不做

		el.style.setProperty(COLOR_VAR, getComputedStyle(el).color);
		el.style.setProperty(TEXT_VAR, natural + GAP + "px");
		el.style.setProperty(DURATION_VAR, Math.max(MIN_CYCLE, (natural + GAP) / SPEED).toFixed(1) + "s");
		el.setAttribute(TEXT_ATTR, text);
		el.setAttribute(ATTR, "");
	}

	/**
	 * 设置里「文字 + 开关」的行：把文字列变成开关的"大号按钮"。
	 *
	 * 只绑文字列（Row 里那个 min-w-0 的直系子元素），不碰控件列：
	 * 控件列里有数字输入框，整行可点会把"点输入框"也变成切开关。
	 * React 重渲染会换掉节点，所以每次轮询都重查；用属性做幂等标记，重复绑不会叠加。
	 */
	function bindSwitchRows() {
		var switches = document.querySelectorAll('.settings-dialog [role="switch"]');
		for (var i = 0; i < switches.length; i++) {
			var sw = switches[i];
			var row = sw.closest(".hairline-b");
			if (!row || row.getAttribute(ROW_BOUND_ATTR) === "1") continue;
			// Row 的文字列：hairline-b 的直系子元素里带 min-w-0 的那个
			var label = null;
			for (var c = 0; c < row.children.length; c += 1) {
				if (row.children[c].classList.contains("min-w-0")) { label = row.children[c]; break; }
			}
			if (!label) continue;
			row.setAttribute(ROW_BOUND_ATTR, "1");
			(function (button, labelEl) {
				labelEl.style.cursor = "pointer";
				labelEl.addEventListener("click", function (event) {
					// 文字里可能有链接/按钮，别抢它们
					if (event.target.closest("a, button, input, select, textarea")) return;
					if (button.disabled) return;
					event.preventDefault();
					button.click();
				});
			})(sw, label);
		}
	}

	// 模型名会随会话/选择变化，输入卡也会整体重挂载；轮询最省事，且因为有上面的
	// 提前返回，稳态下每次只花一个 querySelector。
	function start() {
		apply();
		bindSwitchRows();
		setInterval(function () { apply(); bindSwitchRows(); }, 800);
		window.addEventListener("resize", apply, { passive: true });
		window.addEventListener("orientationchange", apply, { passive: true });
	}

	if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start, { once: true });
	else start();
})();
